            if (x < 0 || x >= w) { hideTooltip(); return; }
            var eta = etaFromX(x, w, params);
            var I = intensityAtEta(eta, params);
            tooltip.textContent = 'η=' + eta.toFixed(5) + '  I=' + (I * 100).toFixed(1) + '%';
