            modal.classList.add('open');
            modalOpen = true;
            var closeBtn = document.getElementById('modal-close-button');
            if (closeBtn) closeBtn.focus();
        }

        function closeModal() {
            var modal = document.getElementById('principle-modal');
            if (!modal) return;
            modal.classList.remove('open');
            modalOpen = false;
            if (lastFocused && lastFocused.focus) lastFocused.focus();
        }

        function trapTab(e) {
            if (!modalOpen) return;
            var modal = document.getElementById('principle-modal');
            var inner = modal.querySelector('.modal-inner');
            var focusable = inner.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
            if (focusable.length === 0) return;
            var first = focusable[0];
            var last = focusable[focusable.length - 1];
            if (e.key === 'Tab') {
                if (e.shiftKey) {
                    if (document.activeElement === first) { e.preventDefault(); last.focus(); }
                } else {
                    if (document.activeElement === last) { e.preventDefault(); first.focus(); }
                }
            }
        }

        function init() {
            readURL();
            syncInputs();

            // Input listeners
            for (var i = 0; i < KEYS.length; i++) {
                (function(k) {
                    var inp = document.getElementById(k);
                    if (inp) {
                        inp.addEventListener('input', function() {
                            var v = parseFloat(inp.value);
                            if (!isFinite(v)) v = DEFAULTS[k];
                            params[k] = clamp(v, LIMITS[k][0], LIMITS[k][1]);
                            if (k === 'slitSeparation' || k === 'slitWidth') {
