            document.getElementById('reset-button').addEventListener('click', function() {
                params = normalizeParams({});
                syncInputs();
                render();
            });

            document.getElementById('theme-button').addEventListener('click', function() {
                applyTheme(theme === 'dark' ? 'light' : 'dark');
                render();
            });

            document.getElementById('palette-button').addEventListener('click', function() {
                applyPalette(palette === 'color' ? 'grayscale' : 'color');
                render();
            });

            document.getElementById('principle-button').addEventListener('click', openModal);
            document.getElementById('modal-close-button').addEventListener('click', closeModal);

            var modal = document.getElementById('principle-modal');
