            // Canvas hover
            var intensityCanvas = document.getElementById('intensityCanvas');
            intensityCanvas.addEventListener('pointermove', function(e) {
                var rect = intensityCanvas.getBoundingClientRect();
                var x = e.clientX - rect.left;
                setHover(Math.round(x));
            });
            intensityCanvas.addEventListener('pointerleave', function() {
                setHover(-1);
            });

            // Keyboard on intensity canvas
            intensityCanvas.addEventListener('keydown', function(e) {
                var w = intensityCanvas.parentElement.clientWidth;
                var cx = (hoverX >= 0) ? hoverX : Math.round(w / 2);
                if (e.key === 'Home') { cx = 0; e.preventDefault(); }
                else if (e.key === 'End') { cx = w - 1; e.preventDefault(); }
                else if (e.key === 'ArrowLeft') { cx = Math.max(0, cx - 2); e.preventDefault(); }
                else if (e.key === 'ArrowRight') { cx = Math.min(w - 1, cx + 2); e.preventDefault(); }
                else return;
                setHover(cx);
            });

            intensityCanvas.addEventListener('focus', function() {
                var w = intensityCanvas.parentElement.clientWidth;
                if (hoverX < 0) setHover(Math.round(w / 2));
            });

            intensityCanvas.addEventListener('blur', function() {
