            });

            // Resize
            var resizeTimer = null;
            window.addEventListener('resize', function() {
                if (resizeTimer) clearTimeout(resizeTimer);
                resizeTimer = setTimeout(function() { render(); }, 50);
            });

            // First render
            render();
            firstFrameDone = true;
            if (readyResolve) readyResolve(true);
        }

        // Public API
        window.PhySim = {
            version: VERSION,
            defaults: JSON.parse(JSON.stringify(DEFAULTS)),
            limits: JSON.parse(JSON.stringify(LIMITS)),
            ready: readyPromise,
            getParams: function() {
                return { wavelength: params.wavelength, slitSeparation: params.slitSeparation, slitWidth: params.slitWidth, screenDistance: params.screenDistance, zoom: params.zoom };
            },
            setParams: function(partial) {
