                render();
            },
            intensityAtEta: function(eta, p) {
                return intensityAtEta(eta, p || params);
            },
            getCriticalMarkers: function(p) {
                return getCriticalMarkers(p || params);
            },
            render: function() {
                render();
            }
        };

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', init);
        } else {
            init();
        }
    })();
